draw:
var F = p.force, r = p.dist, th = p.angle * Math.PI / 180;
var cx = W * 0.26, cy = H * 0.66;
var len = (r / 0.50) * (W * 0.40);
var ux = Math.cos(th), uy = -Math.sin(th);
var ax = cx + len, ay = cy;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

// line of action, dashed, extended both ways
ctx.strokeStyle = C.faint;
ctx.setLineDash([4, 4]);
ctx.beginPath();
ctx.moveTo(ax - ux * W, ay - uy * W);
ctx.lineTo(ax + ux * W, ay + uy * W);
ctx.stroke();
ctx.setLineDash([]);

// handle
ctx.strokeStyle = C.ink;
ctx.lineWidth = 5;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(ax, ay); ctx.stroke();
ctx.lineWidth = 2;

// bolt
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(cx, cy, 9, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("pivot (bolt)", cx - 22, cy + 26);

// r label along handle
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(cx, cy - 16); ctx.lineTo(ax, ay - 16); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("r = " + r.toFixed(2) + " m", (cx + ax) / 2 - 26, cy - 22);

// lever arm: foot of perpendicular from pivot onto the line of action
var vx = cx - ax, vy = cy - ay;
var s = vx * ux + vy * uy;
var fx = ax + s * ux, fy = ay + s * uy;
ctx.strokeStyle = C.accent;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(fx, fy); ctx.stroke();
ctx.setLineDash([]);
var rperp = Math.abs(r * Math.sin(th));
ctx.fillStyle = C.accent;
ctx.fillText("lever arm " + rperp.toFixed(3) + " m", (cx + fx) / 2 - 40, (cy + fy) / 2 - 8);

// force arrow at the handle end
var alen = (F / 200) * (W * 0.24) + 14;
var ex = ax + ux * alen, ey = ay + uy * alen;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(ex, ey); ctx.stroke();
ctx.beginPath();
ctx.moveTo(ex, ey);
ctx.lineTo(ex - ux * 11 - uy * 6, ey - uy * 11 + ux * 6);
ctx.lineTo(ex - ux * 11 + uy * 6, ey - uy * 11 - ux * 6);
ctx.closePath();
ctx.fillStyle = C.figure;
ctx.fill();
ctx.fillText("F = " + F.toFixed(0) + " N", ex + 6, ey - 6);

// angle marker at the handle end
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.arc(ax, ay, 26, -th, 0, th > 0); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText(p.angle.toFixed(0) + " deg", ax + 30, ay - 10);

var tau = r * F * Math.sin(th);
ctx.fillStyle = C.ink;
ctx.fillText("torque = r F sin(angle) = lever arm x F", 14, H - 12);
out.note = "tau = " + Math.abs(tau).toFixed(1) + " N·m   (lever arm " + rperp.toFixed(3) + " m x " + F.toFixed(0) + " N)";
